function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 70) return 'grid needs 2 to 70 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 2 || cols > 70) return 'grid needs 2 to 70 columns.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each cell holds 0 to 100 cherries.';
  }
  return null;
}

