function cherryPickup(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let dp = Array.from({ length: cols }, () => new Array(cols).fill(0));
  for (let row = rows - 1; row >= 0; row--) {
    const next = Array.from({ length: cols }, () => new Array(cols).fill(0));
    for (let c1 = 0; c1 < cols; c1++) {
      for (let c2 = 0; c2 < cols; c2++) {
        let best = 0;
        for (let d1 = -1; d1 <= 1; d1++) {
          for (let d2 = -1; d2 <= 1; d2++) {
            const n1 = c1 + d1;
            const n2 = c2 + d2;
            if (n1 >= 0 && n1 < cols && n2 >= 0 && n2 < cols) {
              best = Math.max(best, dp[n1][n2]);
            }
          }
        }
        const picked = c1 === c2 ? grid[row][c1] : grid[row][c1] + grid[row][c2];
        next[c1][c2] = picked + best;
      }
    }
    dp = next;
  }
  return dp[0][cols - 1];
}

