function cherryPickup(grid) {
  const rows = grid.length, cols = grid[0].length;
  let answer = 0;
  // Walk every pair of paths from the top, carrying the total so far; no memo.
  const walk = (row, x, y, sum) => {
    const gain = x === y ? grid[row][x] : grid[row][x] + grid[row][y];
    if (row === rows - 1) { answer = Math.max(answer, sum + gain); return; }
    for (const nx of [x - 1, x, x + 1]) {
      if (nx < 0 || nx >= cols) continue;
      for (const ny of [y - 1, y, y + 1]) {
        if (ny < 0 || ny >= cols) continue;
        walk(row + 1, nx, ny, sum + gain);
      }
    }
  };
  walk(0, 0, cols - 1, 0);
  return answer;
}

