function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 60 + Math.floor(rand() * 11) : 2 + Math.floor(rand() * 4);
  const cols = large ? 60 + Math.floor(rand() * 11) : 2 + Math.floor(rand() * 5);
  const max = large ? 100 : [1, 5, 20, 100][Math.floor(rand() * 4)];
  const empty = rand() * 0.7;
  const grid = [];
  for (let r = 0; r < rows; r++) {
    const line = [];
    for (let c = 0; c < cols; c++) line.push(rand() < empty ? 0 : Math.floor(rand() * (max + 1)));
    grid.push(line);
  }
  return [grid];
}
